415	/**
416	 * Adjust labels on x direction to avoid overlap.
417	 */
418	export function shiftLayoutOnX(
419	    list: Pick<LabelLayoutInfoComputed, 'rect' | 'label'>[],
420	    leftBound: number,
421	    rightBound: number,
422	    // If average the shifts on all labels and add them to 0
423	    // TODO: Not sure if should enable it.
424	    // Pros: The angle of lines will distribute more equally
425	    // Cons: In some layout. It may not what user wanted. like in pie. the label of last sector is usually changed unexpectedly.
426	    balanceShift?: boolean
427	): boolean {
428	    return shiftLayout(list, 'x', 'width', leftBound, rightBound, balanceShift);
429	}
430	
431	/**
432	 * Adjust labels on y direction to avoid overlap.
433	 */
434	export function shiftLayoutOnY(
435	    list: Pick<LabelLayoutInfoComputed, 'rect' | 'label'>[],
436	    topBound: number,
437	    bottomBound: number,
438	    // If average the shifts on all labels and add them to 0
439	    balanceShift?: boolean
440	): boolean {
441	    return shiftLayout(list, 'y', 'height', topBound, bottomBound, balanceShift);
442	}
443	
444	/**
445	 * [CAUTION]: the `label.ignore` in the input is not necessarily falsy.
446	 *  this method checks intersection regardless of current `ignore`,
447	 *  if no intersection, restore the `ignore` to `defaultAttr.ignore`.
448	 *  And `labelList` will be modified.
449	 *  Therefore, if some other overlap resolving strategy has ignored some elements,
450	 *  do not input them to this method.
451	 * PENDING: review the diff between the requirements from LabelManager and AxisBuilder,
452	 *  and uniform the behavior?
453	 */
454	export function hideOverlap(labelList: LabelLayoutInfoAll[]): void {
455	    const displayedLabels: LabelLayoutInfoComputed[] = [];
456	
457	    // TODO, render overflow visible first, put in the displayedLabels.
458	    labelList.sort(function (a, b) {
459	        return ((b.suggestIgnore ? 1 : 0) - (a.suggestIgnore ? 1 : 0))
460	            || (b.priority - a.priority);
461	    });
462	
463	    function hideEl(el: Element) {
464	        if (!el.ignore) {
465	            // Show on emphasis.
466	            const emphasisState = el.ensureState('emphasis');
467	            if (emphasisState.ignore == null) {
468	                emphasisState.ignore = false;
469	            }
470	        }
471	
472	        el.ignore = true;
473	    }
474	
475	    for (let i = 0; i < labelList.length; i++) {
476	        const labelItem = ensureLabelLayoutInfoComputed(labelList[i]);
477	
478	        if (!labelItem || labelItem.label.ignore) {
479	            continue;
480	        }
481	
482	        const label = labelItem.label;
483	        const labelLine = labelItem.labelLine;
484	
485	        // NOTICE: even when the with/height of globalRect of a label is 0, the label line should
486	        // still be displayed, since we should follow the concept of "truncation", meaning that
487	        // something exists even if it cannot be fully displayed. A visible label line is necessary
488	        // to allow users to get a tooltip with label info on hover.
489	
490	        let overlapped = false;
491	        for (let j = 0; j < displayedLabels.length; j++) {
492	            if (labelIntersect(labelItem, displayedLabels[j], null, {touchThreshold: 0.05})) {
493	                overlapped = true;
494	                break;
495	            }
496	        }
497	
498	        // TODO Callback to determine if this overlap should be handled?
499	        if (overlapped) {
500	            hideEl(label);
501	            labelLine && hideEl(labelLine);
502	        }
503	        else {
504	            label.attr('ignore', labelItem.defaultAttr.ignore);
505	            labelLine && labelLine.attr('ignore', labelItem.defaultAttr.labelGuideIgnore);
506	
507	            displayedLabels.push(labelItem);
508	        }
509	    }
510	}
511	
512	/**
513	 * [NOTICE]:
514	 *  - `label.ignore` is not considered - no requirement so far.
515	 *  - `baseLayoutInfo` and `targetLayoutInfo` may be modified - obb may be created and saved.
516	 *
517	 * Enable fast check for performance; use obb if inevitable.
518	 * If `mtv` is used, `targetLayoutInfo` can be moved based on the values filled into `mtv`.
519	 */
520	export function labelIntersect(
521	    baseLayoutInfo: LabelIntersectionCheckInfo | NullUndefined,
522	    targetLayoutInfo: LabelIntersectionCheckInfo | NullUndefined,
523	    mtv?: PointLike,
524	    intersectOpt?: BoundingRectIntersectOpt
525	): boolean {
526	    if (!baseLayoutInfo || !targetLayoutInfo) {
527	        return false;
528	    }
529	    // Fast rejection.
530	    if (!baseLayoutInfo.rect.intersect(targetLayoutInfo.rect, mtv, intersectOpt)) {
531	        return false;
532	    }
533	    if (baseLayoutInfo.axisAligned && targetLayoutInfo.axisAligned) {
534	        return true; // obb is the same as the normal bounding rect.
535	    }
536	    return ensureOBB(baseLayoutInfo).intersect(ensureOBB(targetLayoutInfo), mtv, intersectOpt);
537	}

