20	// FIXME emphasis label position is not same with normal label position
21	import {parsePercent} from '../../util/number';
22	import PieSeriesModel, { PieSeriesOption, PieDataItemOption } from './PieSeries';
23	import { VectorArray } from 'zrender/src/core/vector';
24	import { HorizontalAlign, ZRTextAlign } from '../../util/types';
25	import { Sector, Polyline, Point } from '../../util/graphic';
26	import ZRText from 'zrender/src/graphic/Text';
27	import BoundingRect, {RectLike} from 'zrender/src/core/BoundingRect';
28	import { each, isNumber } from 'zrender/src/core/util';
29	import { limitTurnAngle, limitSurfaceAngle } from '../../label/labelGuideHelper';
30	import { shiftLayoutOnY } from '../../label/labelLayoutHelper';
31	
32	const RADIAN = Math.PI / 180;
33	
34	interface LabelLayout {
35	    label: ZRText
36	    labelLine: Polyline
37	    position: PieSeriesOption['label']['position']
38	    len: number
39	    len2: number
40	    minTurnAngle: number
41	    maxSurfaceAngle: number
42	    surfaceNormal: Point
43	    linePoints: VectorArray[]
44	    textAlign: HorizontalAlign
45	    labelDistance: number
46	    labelAlignTo: PieSeriesOption['label']['alignTo']
47	    edgeDistance: number
48	    bleedMargin: PieSeriesOption['label']['bleedMargin']
49	    rect: BoundingRect
50	    /**
51	     * user-set style.width.
52	     * This is useful because label.style.width might be changed
53	     * by constrainTextWidth.
54	     */
55	    labelStyleWidth: number
56	    unconstrainedWidth: number
57	    targetTextWidth?: number
58	}
59	
60	function adjustSingleSide(
61	    list: LabelLayout[],
62	    cx: number,
63	    cy: number,
64	    r: number,
65	    dir: -1 | 1,
66	    viewWidth: number,
67	    viewHeight: number,
68	    viewLeft: number,
69	    viewTop: number,
70	    farthestX: number
71	) {
72	    if (list.length < 2) {
73	        return;
74	    }
75	
76	    interface SemiInfo {
77	        list: LabelLayout[]
78	        rB: number
79	        maxY: number
80	    };
81	
82	    function recalculateXOnSemiToAlignOnEllipseCurve(semi: SemiInfo) {
83	        const rB = semi.rB;
84	        const rB2 = rB * rB;
85	        for (let i = 0; i < semi.list.length; i++) {
86	            const item = semi.list[i];
87	            const dy = Math.abs(item.label.y - cy);
88	            // horizontal r is always same with original r because x is not changed.
89	            const rA = r + item.len;
90	            const rA2 = rA * rA;
91	            // Use ellipse implicit function to calculate x
92	            const dx = Math.sqrt(Math.abs((1 - dy * dy / rB2) * rA2));
93	            const newX = cx + (dx + item.len2) * dir;
94	            const deltaX = newX - item.label.x;
95	            const newTargetWidth = item.targetTextWidth - deltaX * dir;
96	            // text x is changed, so need to recalculate width.
97	            constrainTextWidth(item, newTargetWidth, true);
98	            item.label.x = newX;
99	        }
100	    }
101	
102	    // Adjust X based on the shifted y. Make tight labels aligned on an ellipse curve.
103	    function recalculateX(items: LabelLayout[]) {
104	        // Extremes of
105	        const topSemi = { list: [], maxY: 0} as SemiInfo;
106	        const bottomSemi = { list: [], maxY: 0 } as SemiInfo;
107	
108	        for (let i = 0; i < items.length; i++) {
109	            if (items[i].labelAlignTo !== 'none') {
110	                continue;
111	            }
112	            const item = items[i];
113	            const semi = item.label.y > cy ? bottomSemi : topSemi;
114	            const dy = Math.abs(item.label.y - cy);
115	            if (dy >= semi.maxY) {
116	                const dx = item.label.x - cx - item.len2 * dir;
117	                // horizontal r is always same with original r because x is not changed.
118	                const rA = r + item.len;
119	                // Canculate rB based on the topest / bottemest label.
120	                const rB = Math.abs(dx) < rA
121	                    ? Math.sqrt(dy * dy / (1 - dx * dx / rA / rA))
122	                    : rA;
123	                semi.rB = rB;
124	                semi.maxY = dy;
125	            }
126	            semi.list.push(item);
127	        }
128	
129	        recalculateXOnSemiToAlignOnEllipseCurve(topSemi);
130	        recalculateXOnSemiToAlignOnEllipseCurve(bottomSemi);
131	    }
132	
133	    const len = list.length;
134	    for (let i = 0; i < len; i++) {
135	        if (list[i].position === 'outer' && list[i].labelAlignTo === 'labelLine') {
136	            const dx = list[i].label.x - farthestX;
137	            list[i].linePoints[1][0] += dx;
138	            list[i].label.x = farthestX;
139	        }
140	    }
141	
142	    if (shiftLayoutOnY(list, viewTop, viewTop + viewHeight)) {
143	        recalculateX(list);
144	    }
145	}
146	
147	function avoidOverlap(
148	    labelLayoutList: LabelLayout[],
149	    cx: number,
150	    cy: number,
151	    r: number,
152	    viewWidth: number,
153	    viewHeight: number,
154	    viewLeft: number,
155	    viewTop: number
156	) {
157	    const leftList = [];
158	    const rightList = [];
159	    let leftmostX = Number.MAX_VALUE;
160	    let rightmostX = -Number.MAX_VALUE;
161	    for (let i = 0; i < labelLayoutList.length; i++) {
162	        const label = labelLayoutList[i].label;
163	        if (isPositionCenter(labelLayoutList[i])) {
164	            continue;
165	        }
166	        if (label.x < cx) {
167	            leftmostX = Math.min(leftmostX, label.x);
168	            leftList.push(labelLayoutList[i]);
169	        }
170	        else {
171	            rightmostX = Math.max(rightmostX, label.x);
172	            rightList.push(labelLayoutList[i]);
173	        }
174	    }
175	
176	    for (let i = 0; i < labelLayoutList.length; i++) {
177	        const layout = labelLayoutList[i];
178	        if (!isPositionCenter(layout) && layout.linePoints) {
179	            if (layout.labelStyleWidth != null) {
180	                continue;
181	            }
182	
183	            const label = layout.label;
184	            const linePoints = layout.linePoints;
185	
186	            let targetTextWidth;
187	            if (layout.labelAlignTo === 'edge') {
188	                if (label.x < cx) {
189	                    targetTextWidth = linePoints[2][0] - layout.labelDistance
190	                            - viewLeft - layout.edgeDistance;
191	                }
192	                else {
193	                    targetTextWidth = viewLeft + viewWidth - layout.edgeDistance
194	                            - linePoints[2][0] - layout.labelDistance;
195	                }
196	            }
197	            else if (layout.labelAlignTo === 'labelLine') {
198	                if (label.x < cx) {
199	                    targetTextWidth = leftmostX - viewLeft - layout.bleedMargin;
200	                }
201	                else {
202	                    targetTextWidth = viewLeft + viewWidth - rightmostX - layout.bleedMargin;
203	                }
204	            }
205	            else {
206	                if (label.x < cx) {
207	                    targetTextWidth = label.x - viewLeft - layout.bleedMargin;
208	                }
209	                else {
210	                    targetTextWidth = viewLeft + viewWidth - label.x - layout.bleedMargin;
211	                }
212	            }
213	            layout.targetTextWidth = targetTextWidth;
214	
215	            constrainTextWidth(layout, targetTextWidth);
216	        }
217	    }
218	
219	    adjustSingleSide(rightList, cx, cy, r, 1, viewWidth, viewHeight, viewLeft, viewTop, rightmostX);
220	    adjustSingleSide(leftList, cx, cy, r, -1, viewWidth, viewHeight, viewLeft, viewTop, leftmostX);
221	
222	    for (let i = 0; i < labelLayoutList.length; i++) {
223	        const layout = labelLayoutList[i];
224	        if (!isPositionCenter(layout) && layout.linePoints) {
225	            const label = layout.label;
226	            const linePoints = layout.linePoints;
227	            const isAlignToEdge = layout.labelAlignTo === 'edge';
228	            const padding = label.style.padding as number[];
229	            const paddingH = padding ? padding[1] + padding[3] : 0;
230	            // textRect.width already contains paddingH if bgColor is set
231	            const extraPaddingH = label.style.backgroundColor ? 0 : paddingH;
232	            const realTextWidth = layout.rect.width + extraPaddingH;
233	            const dist = linePoints[1][0] - linePoints[2][0];
234	            if (isAlignToEdge) {
235	                if (label.x < cx) {
236	                    linePoints[2][0] = viewLeft + layout.edgeDistance + realTextWidth + layout.labelDistance;
237	                }
238	                else {
239	                    linePoints[2][0] = viewLeft + viewWidth - layout.edgeDistance
240	                            - realTextWidth - layout.labelDistance;
241	                }
242	            }
243	            else {
244	                if (label.x < cx) {
245	                    linePoints[2][0] = label.x + layout.labelDistance;
246	                }
247	                else {
248	                    linePoints[2][0] = label.x - layout.labelDistance;
249	                }
250	                linePoints[1][0] = linePoints[2][0] + dist;
251	            }
252	            linePoints[1][1] = linePoints[2][1] = label.y;
253	        }
254	    }
255	}
