257	/**
258	 * Set max width of each label, and then wrap each label to the max width.
259	 *
260	 * @param layout label layout
261	 * @param availableWidth max width for the label to display
262	 * @param forceRecalculate recaculate the text layout even if the current width
263	 * is smaller than `availableWidth`. This is useful when the text was previously
264	 * wrapped by calling `constrainTextWidth` but now `availableWidth` changed, in
265	 * which case, previous wrapping should be redo.
266	 */
267	function constrainTextWidth(
268	    layout: LabelLayout,
269	    availableWidth: number,
270	    forceRecalculate: boolean = false
271	) {
272	    if (layout.labelStyleWidth != null) {
273	        // User-defined style.width has the highest priority.
274	        return;
275	    }
276	
277	    const label = layout.label;
278	    const style = label.style;
279	    const textRect = layout.rect;
280	    const bgColor = style.backgroundColor;
281	    const padding = style.padding as number[];
282	    const paddingH = padding ? padding[1] + padding[3] : 0;
283	    const overflow = style.overflow;
284	
285	    // textRect.width already contains paddingH if bgColor is set
286	    const oldOuterWidth = textRect.width + (bgColor ? 0 : paddingH);
287	    if (availableWidth < oldOuterWidth || forceRecalculate) {
288	        const oldHeight = textRect.height;
289	        if (overflow && overflow.match('break')) {
290	            // Temporarily set background to be null to calculate
291	            // the bounding box without background.
292	            label.setStyle('backgroundColor', null);
293	            // Set constraining width
294	            label.setStyle('width', availableWidth - paddingH);
295	
296	            // This is the real bounding box of the text without padding.
297	            const innerRect = label.getBoundingRect();
298	
299	            label.setStyle('width', Math.ceil(innerRect.width));
300	            label.setStyle('backgroundColor', bgColor);
301	        }
302	        else {
303	            const availableInnerWidth = availableWidth - paddingH;
304	            const newWidth = availableWidth < oldOuterWidth
305	                // Current text is too wide, use `availableWidth` as max width.
306	                ? availableInnerWidth
307	                : (
308	                    // Current available width is enough, but the text may have
309	                    // already been wrapped with a smaller available width.
310	                    forceRecalculate
311	                        ? (availableInnerWidth > layout.unconstrainedWidth
312	                            // Current available is larger than text width,
313	                            // so don't constrain width (otherwise it may have
314	                            // empty space in the background).
315	                            ? null
316	                            // Current available is smaller than text width, so
317	                            // use the current available width as constraining
318	                            // width.
319	                            : availableInnerWidth
320	                        )
321	                    // Current available width is enough, so no need to
322	                    // constrain.
323	                    : null
324	                );
325	            label.setStyle('width', newWidth);
326	        }
327	
328	        const newRect = label.getBoundingRect();
329	        textRect.width = newRect.width;
330	        const margin = ((label.style.margin as number) || 0) + 2.1;
331	        textRect.height = newRect.height + margin;
332	        textRect.y -= (textRect.height - oldHeight) / 2;
333	    }
334	}
335	
336	function isPositionCenter(sectorShape: LabelLayout) {
337	    // Not change x for center label
338	    return sectorShape.position === 'center';
339	}
340	
341	export default function pieLabelLayout(
342	    seriesModel: PieSeriesModel
343	) {
344	    const data = seriesModel.getData();
345	    const labelLayoutList: LabelLayout[] = [];
346	    let cx;
347	    let cy;
348	    let hasLabelRotate = false;
349	    const minShowLabelRadian = (seriesModel.get('minShowLabelAngle') || 0) * RADIAN;
350	
351	    const viewRect = data.getLayout('viewRect') as RectLike;
352	    const r = data.getLayout('r') as number;
353	    const viewWidth = viewRect.width;
354	    const viewLeft = viewRect.x;
355	    const viewTop = viewRect.y;
356	    const viewHeight = viewRect.height;
357	
358	    function setNotShow(el: {ignore: boolean}) {
359	        el.ignore = true;
360	    }
361	
362	    function isLabelShown(label: ZRText) {
363	        if (!label.ignore) {
364	            return true;
365	        }
366	        for (const key in label.states) {
367	            if (label.states[key].ignore === false) {
368	                return true;
369	            }
370	        }
371	        return false;
372	    }
373	
374	    data.each(function (idx) {
375	        const sector = data.getItemGraphicEl(idx) as Sector;
376	        const sectorShape = sector.shape;
377	        const label = sector.getTextContent();
378	        const labelLine = sector.getTextGuideLine();
379	
380	        const itemModel = data.getItemModel<PieDataItemOption>(idx);
381	        const labelModel = itemModel.getModel('label');
382	        // Use position in normal or emphasis
383	        const labelPosition = labelModel.get('position') || itemModel.get(['emphasis', 'label', 'position']);
384	        const labelDistance = labelModel.get('distanceToLabelLine');
385	        const labelAlignTo = labelModel.get('alignTo');
386	        const edgeDistance = parsePercent(labelModel.get('edgeDistance'), viewWidth);
387	        let bleedMargin = labelModel.get('bleedMargin');
388	        if (bleedMargin == null) {
389	            // An arbitrary strategy for small viewRect - especial pie is layout in calendar or matrix coord sys.
390	            bleedMargin = Math.min(viewWidth, viewHeight) > 200 ? 10 : 2;
391	        }
392	
393	        const labelLineModel = itemModel.getModel('labelLine');
394	        let labelLineLen = labelLineModel.get('length');
395	        labelLineLen = parsePercent(labelLineLen, viewWidth);
396	        let labelLineLen2 = labelLineModel.get('length2');
397	        labelLineLen2 = parsePercent(labelLineLen2, viewWidth);
398	
399	        if (Math.abs(sectorShape.endAngle - sectorShape.startAngle) < minShowLabelRadian) {
400	            each(label.states, setNotShow);
401	            label.ignore = true;
402	            if (labelLine) {
403	                each(labelLine.states, setNotShow);
404	                labelLine.ignore = true;
405	            }
406	            return;
407	        }
408	
409	        if (!isLabelShown(label)) {
410	            return;
411	        }
412	
413	        const midAngle = (sectorShape.startAngle + sectorShape.endAngle) / 2;
414	        const nx = Math.cos(midAngle);
415	        const ny = Math.sin(midAngle);
416	
417	        let textX;
418	        let textY;
419	        let linePoints;
420	        let textAlign: ZRTextAlign;
421	
422	        cx = sectorShape.cx;
423	        cy = sectorShape.cy;
424	
425	
426	        const isLabelInside = labelPosition === 'inside' || labelPosition === 'inner';
427	        if (labelPosition === 'center') {
428	            textX = sectorShape.cx;
429	            textY = sectorShape.cy;
430	            textAlign = 'center';
431	        }
432	        else {
433	            const x1 = (isLabelInside ? (sectorShape.r + sectorShape.r0) / 2 * nx : sectorShape.r * nx) + cx;
434	            const y1 = (isLabelInside ? (sectorShape.r + sectorShape.r0) / 2 * ny : sectorShape.r * ny) + cy;
435	
436	            textX = x1 + nx * 3;
437	            textY = y1 + ny * 3;
438	
439	            if (!isLabelInside) {
440	                // For roseType
441	                const x2 = x1 + nx * (labelLineLen + r - sectorShape.r);
442	                const y2 = y1 + ny * (labelLineLen + r - sectorShape.r);
443	                const x3 = x2 + ((nx < 0 ? -1 : 1) * labelLineLen2);
444	                const y3 = y2;
445	
446	                if (labelAlignTo === 'edge') {
447	                    // Adjust textX because text align of edge is opposite
448	                    textX = nx < 0
449	                        ? viewLeft + edgeDistance
450	                        : viewLeft + viewWidth - edgeDistance;
451	                }
452	                else {
453	                    textX = x3 + (nx < 0 ? -labelDistance : labelDistance);
454	                }
455	                textY = y3;
456	                linePoints = [[x1, y1], [x2, y2], [x3, y3]];
457	            }
458	
459	            textAlign = isLabelInside
460	                ? 'center'
461	                : (labelAlignTo === 'edge'
462	                    ? (nx > 0 ? 'right' : 'left')
463	                    : (nx > 0 ? 'left' : 'right'));
464	        }
465	
466	        const PI = Math.PI;
467	        let labelRotate = 0;
468	        const rotate = labelModel.get('rotate');
469	        if (isNumber(rotate)) {
470	            labelRotate = rotate * (PI / 180);
471	        }
472	        else if (labelPosition === 'center') {
473	            labelRotate = 0;
474	        }
475	        else if (rotate === 'radial' || rotate === true) {
476	            const radialAngle = nx < 0 ? -midAngle + PI : -midAngle;
477	            labelRotate = radialAngle;
478	        }
479	        else if (rotate === 'tangential'
480	            && labelPosition !== 'outside' && labelPosition !== 'outer'
481	        ) {
482	            let rad = Math.atan2(nx, ny);
483	            if (rad < 0) {
484	                rad = PI * 2 + rad;
485	            }
486	            const isDown = ny > 0;
487	            if (isDown) {
488	                rad = PI + rad;
489	            }
490	            labelRotate = rad - PI;
491	        }
492	
493	        hasLabelRotate = !!labelRotate;
494	
495	        label.x = textX;
496	        label.y = textY;
497	        label.rotation = labelRotate;
498	
499	        label.setStyle({
500	            verticalAlign: 'middle'
501	        });
502	
503	        // Not sectorShape the inside label
504	        if (!isLabelInside) {
505	            const textRect = label.getBoundingRect().clone();
506	            textRect.applyTransform(label.getComputedTransform());
507	            // Text has a default 1px stroke. Exclude this.
508	            const margin = ((label.style.margin as number) || 0) + 2.1;
509	            textRect.y -= margin / 2;
510	            textRect.height += margin;
511	
512	            labelLayoutList.push({
513	                label,
514	                labelLine,
515	                position: labelPosition,
516	                len: labelLineLen,
517	                len2: labelLineLen2,
518	                minTurnAngle: labelLineModel.get('minTurnAngle'),
519	                maxSurfaceAngle: labelLineModel.get('maxSurfaceAngle'),
520	                surfaceNormal: new Point(nx, ny),
521	                linePoints: linePoints,
522	                textAlign: textAlign,
523	                labelDistance: labelDistance,
524	                labelAlignTo: labelAlignTo,
525	                edgeDistance: edgeDistance,
526	                bleedMargin: bleedMargin,
527	                rect: textRect,
528	                unconstrainedWidth: textRect.width,
529	                labelStyleWidth: label.style.width
530	            });
531	        }
532	        else {
533	            label.setStyle({
534	                align: textAlign
535	            });
536	            const selectState = label.states.select;
537	            if (selectState) {
538	                selectState.x += label.x;
539	                selectState.y += label.y;
540	            }
541	        }
542	        sector.setTextConfig({
543	            inside: isLabelInside
544	        });
545	    });
546	
547	    if (!hasLabelRotate && seriesModel.get('avoidLabelOverlap')) {
548	        avoidOverlap(labelLayoutList, cx, cy, r, viewWidth, viewHeight, viewLeft, viewTop);
549	    }
550	
551	    for (let i = 0; i < labelLayoutList.length; i++) {
552	        const layout = labelLayoutList[i];
553	        const label = layout.label;
554	        const labelLine = layout.labelLine;
555	        const notShowLabel = isNaN(label.x) || isNaN(label.y);
556	        if (label) {
557	            label.setStyle({
558	                align: layout.textAlign
559	            });
560	            if (notShowLabel) {
561	                each(label.states, setNotShow);
562	                label.ignore = true;
563	            }
564	            const selectState = label.states.select;
565	            if (selectState) {
566	                selectState.x += label.x;
567	                selectState.y += label.y;
568	            }
569	        }
570	        if (labelLine) {
571	            const linePoints = layout.linePoints;
572	            if (notShowLabel || !linePoints) {
573	                each(labelLine.states, setNotShow);
574	                labelLine.ignore = true;
575	            }
576	            else {
577	                limitTurnAngle(linePoints, layout.minTurnAngle);
578	                limitSurfaceAngle(linePoints, layout.surfaceNormal, layout.maxSurfaceAngle);
579	
580	                labelLine.setShape({ points: linePoints });
581	
582	                // Set the anchor to the midpoint of sector
583	                label.__hostTarget.textGuideLineConfig = {
584	                    anchor: new Point(linePoints[0][0], linePoints[0][1])
585	                };
586	            }
587	        }
588	    }
589	}

