307	    containPoint(point: number[], seriesModel: PieSeriesModel): boolean {
308	        const data = seriesModel.getData();
309	        const itemLayout = data.getItemLayout(0);
310	        if (itemLayout) {
311	            const dx = point[0] - itemLayout.cx;
312	            const dy = point[1] - itemLayout.cy;
313	            const radius = Math.sqrt(dx * dx + dy * dy);
314	            return radius <= itemLayout.r && radius >= itemLayout.r0;
315	        }
316	    }
